{"code": "from pathlib import Path
import os

image_dir = Path('data_small/test')
all_files = list(image_dir.glob(r'**/*.jpg'))

print(f"Total files: {len(all_files)}")

lfs_files = []
real_images = []

for fp in all_files:
    try:
        with open(fp, 'r') as f:
            content = f.read(100)
            if content.startswith('version https://git-lfs.github.com'):
                lfs_files.append(fp)
            else:
                real_images.append(fp)
    except:
        pass

print(f"LFS pointer files: {len(lfs_files)}")
print(f"Real image files: {len(real_images)}")
print(f"LFS files (first 5): {[str(p) for p in lfs_files[:5]]}")"}

